// 验证URL是否在白名单中
int is_allowed_redirect_url(const char *url) {
    if (!url) return 0;

    // 检查是否为相对URL（允许）
    if (url[0] == '/' && url[1] != '/') {
        return 1;
    }

    // 检查协议
    if (strncmp(url, "http://", 7) != 0 && strncmp(url, "https://", 8) != 0) {
        return 0;
    }

