   import (
       "encoding/xml"
       "fmt"
       "os"
   )

   type User struct {
       Name string `xml:"name"`
       Email string `xml:"email"`
   }

   func main() {
       data := []byte(`<?xml version="1.0"?>
       <!DOCTYPE user [
           <!ENTITY xxe SYSTEM "file:///etc/passwd">
       ]>
       <user>
           <name>&xxe;</name>
           <email>test@example.com</email>
       </user>`)

       var user User
       err := xml.Unmarshal(data, &user)
       if err != nil {
