   import (
       "io/ioutil"
       "log"
       "net/http"
   )

   func handler(w http.ResponseWriter, r *http.Request) {
       fileName := r.URL.Query().Get("file") // 攻击者控制的文件名
       data := []byte("malicious content")
       err := ioutil.WriteFile(fileName, data, 0644)
       if err != nil {
