    Statement stmt = conn.createStatement()
) {
    try (ResultSet rs1 = stmt.executeQuery("SELECT * FROM table1")) {
        // 处理 rs1...
    } // rs1 自动关闭
    try (ResultSet rs2 = stmt.executeQuery("SELECT * FROM table2")) {
