                            // 处理数据...
                        }
                    } finally {
                        if (is != null) {
                            try { is.close(); } catch (IOException e) { /* Log or handle exception */ }
                        }
                    }
                }
            }
        } finally {
            if (zipFile != null) {
                try { zipFile.close(); } catch (IOException e) { /* Log or handle exception */ }
            }
        }
    }
}
```
