        if (!isValidPath($filename, $targetDir)) {
            // 跳过或拒绝处理非法路径文件
            continue;
        }
        // 解压文件到目标目录
        $zip->extractTo($targetDir, array($filename));
    }
    $zip->close();
} else {
    // 处理zip文件打开失败
}
?>
```
